-- Fuel uplift records pulled from a PIUSI dispenser by piusi_logger.py.
-- MySQL 8 / MariaDB 10.5+. Paste into phpMyAdmin's SQL tab with the target
-- database selected.
--
-- One row per '+' frame received. Because reads are destructive, a row is
-- written even when the record can't be decoded: the decoded columns are
-- then NULL, parse_error says why, and raw_hex keeps the bytes so the row
-- can be re-decoded later.

CREATE TABLE IF NOT EXISTS fuel_uplifts (
  id                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  -- Generated by the logger when the frame arrives. Makes inserts
  -- idempotent: a retry after a lost DB connection can't create duplicates.
  capture_id         CHAR(36)        NOT NULL,
  received_at_utc    DATETIME(3)     NOT NULL COMMENT 'when the logger received the frame (UTC)',
  unit_address       CHAR(6)         NOT NULL,

  -- Decoded record. The bowser's clock, as transmitted. The timezone is
  -- whatever the bowser is set to, and the clock may drift (see
  -- docs/PROTOCOL.md).
  uplift_at          DATETIME            NULL COMMENT 'bowser clock, as transmitted',
  person             VARCHAR(10)         NULL,
  key_code           VARCHAR(10)         NULL COMMENT 'registered key / registration',
  litres             DECIMAL(7,2)        NULL,

  -- Undecoded / unconfirmed parts, kept so they can be studied later.
  unknown_hex        CHAR(8)             NULL COMMENT 'record bytes 5-8, undecoded',
  unknown_date_byte  TINYINT UNSIGNED    NULL COMMENT 'only set for the legacy 33-byte layout',
  layout             VARCHAR(8)          NULL COMMENT 'dle (expected) or legacy',
  checksum_matches   VARCHAR(10)         NULL COMMENT 'unstuffed / stuffed / both / NULL = neither',
  parse_error        VARCHAR(255)        NULL,

  raw_hex            VARCHAR(255)    NOT NULL COMMENT 'record params, DLE stuffing removed',
  inserted_at        TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (id),
  UNIQUE KEY uq_capture_id (capture_id),
  KEY ix_uplift_at (uplift_at),
  KEY ix_key_code (key_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
